// Block (composition) — a separated list of customer review summaries.
// Avatar, Rating, Separator, and Stack own their look; this Block owns only arrangement.
import type { ReactNode } from "react";
import { Avatar } from "../components/Avatar";
import { Rating } from "../components/Rating";
import { Separator } from "../components/Separator";
import { Stack } from "../layouts/Stack";
import { SkeletonList } from "./SkeletonList";
import "./ReviewList.css";

export interface ReviewListProps {
  reviews: {
    id: string;
    author: string;
    avatarSrc?: string;
    rating: number;
    body: ReactNode;
    date?: string;
  }[];
  /** Renders skeleton placeholders while reviews are loading. */
  isLoading?: boolean;
  /** Message shown when there are no reviews. */
  emptyLabel?: string;
}

function initials(name: string) {
  return name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase())
    .join("");
}

export function ReviewList({
  reviews,
  isLoading,
  emptyLabel = "No reviews yet",
}: ReviewListProps) {
  if (isLoading) {
    return <SkeletonList rows={3} showAvatar />;
  }
  if (reviews.length === 0) {
    return (
      <p role="status" className="sd-reviewlist__empty sd-type-caption-medium">
        {emptyLabel}
      </p>
    );
  }
  return (
    <Stack as="section" gap="medium" className="sd-reviewlist" aria-label="Customer reviews">
      {reviews.map((review, index) => {
        return (
          <div key={review.id} className="sd-reviewlist__entry">
            {/* `small`: the byline row wraps at narrow widths, and its own row gap is then inside the
                byline, so the body it names sits no closer than that (the attachment law). */}
            <Stack gap="small" as="article" className="sd-reviewlist__review">
              <Stack direction="row" align="center" gap="small" wrap className="sd-reviewlist__header">
                <Avatar size="small" src={review.avatarSrc} alt={review.author}>
                  {initials(review.author)}
                </Avatar>
                {/* The author↔date pair IS this container's whole content, which
                    `token-contract.md` § Choosing a Sys rung answers with `2x-small`;
                    `grid-list.item.content.gap` is the reference and `ActivityFeed` already
                    spends it on the same name-over-meta pair. Without it the pair runs on the
                    two line-heights alone. */}
                <Stack gap="2x-small" className="sd-reviewlist__identity">
                  <h3 className="sd-reviewlist__author sd-type-body-medium">{review.author}</h3>
                  {review.date && (
                    <span className="sd-reviewlist__date sd-type-caption-medium">{review.date}</span>
                  )}
                </Stack>
                {/* Read-only: one image named by the score, so a fraction shows as a part-filled star. */}
                <Rating isReadOnly value={review.rating} size="small" aria-label={`${review.rating} out of 5 stars`} />
              </Stack>
              {/* spacing: attachment — the byline names whose review follows */}
              <>
                <div className="sd-reviewlist__body sd-type-body-medium">{review.body}</div>
              </>
            </Stack>
            {index < reviews.length - 1 && (
              <Separator className="sd-reviewlist__separator" />
            )}
          </div>
        );
      })}
    </Stack>
  );
}

/* ReviewList.css — .sd-reviewlist (Block)
   Arrangement only: each review owns a full-width flow and separated footer edge. */
.sd-reviewlist,
.sd-reviewlist__entry {
  width: 100%;
}

.sd-reviewlist__identity {
  min-width: 0;
  flex: 1 1 auto;
}

.sd-reviewlist__author {
  margin: 0;
}

.sd-reviewlist__body {
  width: 100%;
}

.sd-reviewlist__separator {
  margin-top: var(--sd-space-medium);
}

/* empty state — layout only (muted color inherits default; blocks own no color) */
.sd-reviewlist__empty {
  padding: var(--sd-space-large);
  text-align: center;
}
